# f07 嵐の海峡 - weather_fixed=2 でずっと雨のマップ。
# **雨は「片方だけが空」の攻撃を封じる**ので、航空機は艦も地上も叩けず、
# 逆に対空砲も航空機を落とせない。空戦どうしだけが成立する。
# つまり制空権を取っても水上戦には一切効かず、勝負は海と陸だけでつく。
# 飛行場はあえて置いてあるので、無駄と分かっていて航空に金を割くか選べる。
# 雨は視界-2・地上の移動-1 も常時かかるので、鈍く見通しの悪い戦いになる。
# 180度回転対称。
[map]
name             = 嵐の海峡
width            = 48
height           = 30
turns            = 80
timeout_winner   = -1
weather          = 1
weather_fixed    = 2
funds0           = 3500
funds1           = 3500

